package campus.dao;

import campus.db.DBConnection;
import campus.models.AuditRecord;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.util.ArrayList;
import java.util.List;

/**
 * AuditDAO - Retrieves audit records generated by MySQL DBMS Triggers.
 */
public class AuditDAO {

    public List<AuditRecord> getRecentAuditLogs(int limit) {
        List<AuditRecord> list = new ArrayList<>();
        String sql = "SELECT * FROM audit_trail ORDER BY audit_id DESC LIMIT ?";

        try (Connection conn = DBConnection.getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setInt(1, limit);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    int id = rs.getInt("audit_id");
                    String table = rs.getString("table_name");
                    String action = rs.getString("action_type");
                    String recordId = rs.getString("record_id");
                    String details = rs.getString("details");
                    Timestamp changedAt = rs.getTimestamp("changed_at");

                    list.add(new AuditRecord(id, table, action, recordId, details, changedAt));
                }
            }
        } catch (SQLException e) {
            System.err.println("Error fetching audit logs: " + e.getMessage());
        }
        return list;
    }
}
